"""Eywa named types and typed predicate expressions.

Types are named declarations from a campaign; expressions are the documented
typed predicate arrays.  Evaluation is exact: modulo 2^bits arithmetic for
add/sub, left-to-right short circuiting for Boolean connectives, deep value
equality for eq/ne, and lexical binding for ``all``.  Constants keep their
literal JSON values (no string truncation or padding).
"""


class TypeDef(object):
    """One named type declaration."""

    __slots__ = ('name', 'kind', 'bits', 'maxsize', 'values', 'element',
                 'size', 'fields', 'field_map', 'target')

    def __init__(self, name, kind, bits=None, maxsize=None, values=None,
                 element=None, size=None, fields=None, target=None):
        self.name = name
        self.kind = kind
        self.bits = bits
        self.maxsize = maxsize
        self.values = values
        self.element = element
        self.size = size
        self.fields = fields
        self.field_map = dict(fields) if fields is not None else {}
        self.target = target

    @staticmethod
    def from_json(obj):
        kind = obj['kind']
        fields = None
        if kind == 'struct':
            fields = [(f[0], f[1]) for f in obj['fields']]
        return TypeDef(
            obj['name'], kind,
            bits=obj.get('bits'),
            maxsize=obj.get('maxsize'),
            values=list(obj['values']) if kind == 'enum' else None,
            element=obj.get('element'),
            size=obj.get('size'),
            fields=fields,
            target=obj.get('target'),
        )


class TypeTable(object):
    """All named type declarations with transparent alias resolution."""

    __slots__ = ('defs',)

    def __init__(self, defs):
        self.defs = {}
        for d in defs:
            self.defs[d.name] = d

    def resolve(self, name):
        d = self.defs[name]
        while d.kind == 'alias':
            d = self.defs[d.target]
        return d

    def field_type(self, name, field):
        return self.resolve(name).field_map[field]

    def element_type(self, name):
        return self.resolve(name).element

    def int_bits(self, name):
        return self.resolve(name).bits


# ---------------------------------------------------------------------------
# Predicate expressions
# ---------------------------------------------------------------------------

class Var(object):
    """A lexical variable: module input or nearest enclosing all binding."""

    __slots__ = ('name', 'tn')

    def __init__(self, name, tn):
        self.name = name
        self.tn = tn


class Const(object):
    """A typed literal keeping its exact JSON value."""

    __slots__ = ('tn', 'value')

    def __init__(self, tn, value):
        self.tn = tn
        self.value = value


class Field(object):
    """Struct field projection."""

    __slots__ = ('expr', 'field', 'tn')

    def __init__(self, expr, field, tn):
        self.expr = expr
        self.field = field
        self.tn = tn


class Index(object):
    """Fixed zero-based array index."""

    __slots__ = ('expr', 'index', 'tn')

    def __init__(self, expr, index, tn):
        self.expr = expr
        self.index = index
        self.tn = tn


class All(object):
    """Every element of the array satisfies the predicate under a binding."""

    __slots__ = ('binding', 'array', 'pred')

    def __init__(self, binding, array, pred):
        self.binding = binding
        self.array = array
        self.pred = pred


class Match(object):
    """Full regular-language membership of a string value."""

    __slots__ = ('expr', 'pattern')

    def __init__(self, expr, pattern):
        self.expr = expr
        self.pattern = pattern


class Not(object):
    """Boolean complement."""

    __slots__ = ('expr',)

    def __init__(self, expr):
        self.expr = expr


class Bin(object):
    """Binary operation: comparisons, arithmetic, or Boolean connectives."""

    __slots__ = ('op', 'left', 'right', 'bits')

    def __init__(self, op, left, right, bits):
        self.op = op
        self.left = left
        self.right = right
        self.bits = bits


_BINOPS = frozenset(('eq', 'ne', 'lt', 'le', 'gt', 'ge',
                     'add', 'sub', 'and', 'or', 'implies'))


def type_of(node):
    """Type name of a value expression, or None for Boolean predicates."""
    tn = getattr(node, 'tn', None)
    return tn


def parse_expr(raw, tenv, types):
    """Parse a typed predicate array under a name -> type-name environment."""
    op = raw[0]
    if op == 'var':
        name = raw[1]
        return Var(name, tenv[name])
    if op == 'const':
        return Const(raw[1], raw[2])
    if op == 'field':
        expr = parse_expr(raw[1], tenv, types)
        tn = types.field_type(type_of(expr), raw[2])
        return Field(expr, raw[2], tn)
    if op == 'index':
        expr = parse_expr(raw[1], tenv, types)
        tn = types.element_type(type_of(expr))
        return Index(expr, raw[2], tn)
    if op == 'all':
        array = parse_expr(raw[2], tenv, types)
        etn = types.element_type(type_of(array))
        inner = dict(tenv)
        inner[raw[1]] = etn
        pred = parse_expr(raw[3], inner, types)
        return All(raw[1], array, pred)
    if op == 'match':
        from . import regex as regex_mod
        expr = parse_expr(raw[1], tenv, types)
        return Match(expr, regex_mod.compile_pattern(raw[2]))
    if op == 'not':
        return Not(parse_expr(raw[1], tenv, types))
    if op in _BINOPS:
        left = parse_expr(raw[1], tenv, types)
        right = parse_expr(raw[2], tenv, types)
        bits = None
        if op == 'add' or op == 'sub':
            bits = types.int_bits(type_of(left))
        return Bin(op, left, right, bits)
    raise ValueError('unknown predicate form: %r' % (op,))


def evaluate(node, env):
    """Evaluate a predicate against an environment of recovered values."""
    if isinstance(node, Var):
        return env[node.name]
    if isinstance(node, Const):
        return node.value
    if isinstance(node, Field):
        return evaluate(node.expr, env)[node.field]
    if isinstance(node, Index):
        return evaluate(node.expr, env)[node.index]
    if isinstance(node, All):
        array = evaluate(node.array, env)
        binding = node.binding
        pred = node.pred
        had = binding in env
        old = env.get(binding)
        try:
            for element in array:
                env[binding] = element
                if not evaluate(pred, env):
                    return False
            return True
        finally:
            if had:
                env[binding] = old
            else:
                env.pop(binding, None)
    if isinstance(node, Match):
        return node.pattern.match(evaluate(node.expr, env))
    if isinstance(node, Not):
        return not evaluate(node.expr, env)
    if isinstance(node, Bin):
        op = node.op
        if op == 'and':
            return bool(evaluate(node.left, env)) and bool(evaluate(node.right, env))
        if op == 'or':
            return bool(evaluate(node.left, env)) or bool(evaluate(node.right, env))
        if op == 'implies':
            return (not evaluate(node.left, env)) or bool(evaluate(node.right, env))
        left = evaluate(node.left, env)
        right = evaluate(node.right, env)
        if op == 'eq':
            return left == right
        if op == 'ne':
            return left != right
        if op == 'lt':
            return left < right
        if op == 'le':
            return left <= right
        if op == 'gt':
            return left > right
        if op == 'ge':
            return left >= right
        if op == 'add':
            return (left + right) % (1 << node.bits)
        if op == 'sub':
            return (left - right) % (1 << node.bits)
        raise ValueError('unknown binary operator: %r' % (op,))
    raise ValueError('unknown expression node')
